274	  /// Spawn the surface's PTY *without* waiting for window mount (issue #67, background run). Normally
275	  /// `createSurface` fires from `viewDidMoveToWindow`, so a run tab that's started in the background and
276	  /// never made active would never mount — and its command would never start (the toast would claim
277	  /// "running" while nothing ran). `createSurface` only hard-requires positive bounds
278	  /// (`backingPixelSize`); every window reference inside it is a soft fallback. So give the view a
279	  /// non-zero frame and create the surface now; it re-sizes correctly when it later mounts into a real
280	  /// pane. No-op if the surface already exists or this is a test view (`spawnsSurface == false`).
281	  func ensureSurfaceCreated(initialSize: CGSize) {
282	    guard spawnsSurface, surface == nil else { return }
283	    if bounds.width <= 0 || bounds.height <= 0 {
284	      // Positive bounds are the one thing `createSurface` can't proceed without (it defers via
285	      // `pendingSurfaceCreation` otherwise). A sane initial size also gives the spawned command a
286	      // reasonable COLUMNS/LINES until the first on-window resize.
287	      let size =
288	        (initialSize.width > 0 && initialSize.height > 0)
289	        ? initialSize : CGSize(width: 800, height: 480)
290	      setFrameSize(size)
291	    }
292	    createSurface()
293	  }
